// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;

    function setUp() public { c = new W_WALLET(address(new Log())); }

    // fuzz params: withdraw amount and initial deposit amount
    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt) public {
        vm.assume(depositAmt <= VALUE_CAP);
        // keep values in a reasonable range and nonzero
        depositAmt = bound(depositAmt, 1 ether, 10 ether);
        withdrawAmt = bound(withdrawAmt, 1 wei, 10 ether);

        // deploy a reentrant attacker that will reenter exactly once when receiving funds
        Attacker atk = new Attacker(address(c));

        // fund attacker externally so it can call Put
        vm.deal(address(atk), depositAmt + 1 ether);

        // set up Acc for attacker by calling Put via the attacker (attacker forwards to c.Put)
        // attacker will call c.Put{value: depositAmt}(0)
        atk.doPut{value: depositAmt}();

        // ensure deposit satisfied MinSum in C (MinSum == 1 ether in reference)
        vm.warp(block.timestamp + 1);

        // record balance before Collect
        (uint256 unlockBefore, uint256 balBefore) = c.Acc(address(atk));

        // sanity: require preconditions for Collect path we target
        vm.assume(balBefore >= 1 ether);
        vm.assume(balBefore >= withdrawAmt);
        vm.assume(block.timestamp > unlockBefore);

        // Allow the attacker contract to reenter exactly once during the receive when c sends funds
        atk.enableReenter(true);

        // Perform Collect called by the attacker; it will forward the call so msg.sender in c is attacker
        // give attacker some gas and execute
        bool ok;
        try atk.doCollect{value: 0}(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the operation (whether success or not), read the recorded Acc for attacker
        (, uint256 balAfter) = c.Acc(address(atk));

        // General property to assert: on the correct contract, a single Collect call that succeeds
        // always reduces the caller's Acc balance by EXACTLY withdrawAmt. We assert that if the overall
        // outer Collect call returned OK, then balAfter == balBefore - withdrawAmt.
        // The mutant that subtracts balance after the external call can be reentered to withdraw more,
        // causing balAfter to be < balBefore - withdrawAmt for some inputs; the fuzzer can find such inputs.
        if (ok) {
            assertTrue(balAfter == balBefore - withdrawAmt);
        } else {
            // if the outer call reverted/failed, we cannot make a guarantee about balance; accept both
            assertTrue(true);
        }
    }
}

// Attacker contract: records and enables a single reentrant Collect during receive
contract Attacker {
    W_WALLET public c;
    bool public reenterEnabled;
    bool private __entered;

    constructor(address _c) {
        c = W_WALLET(payable(_c));
        reenterEnabled = false;
        __entered = false;
    }

    // fund and call Put on c to set up Acc for this attacker
    function doPut() external payable {
        // forward to c.Put so c.Acc[msg.sender] is set to this contract
        c.Put{value: msg.value}(block.timestamp - 1);
    }

    // call Collect on c as this contract
    function doCollect(uint256 _am) external payable {
        // call c.Collect as this contract
        c.Collect{value: 0}(_am);
    }

    function enableReenter(bool e) external {
        reenterEnabled = e;
    }

    receive() external payable {
        // when receiving funds from c during Collect, attempt exactly one reentrant Collect
        if (reenterEnabled && !__entered) {
            __entered = true;
            // attempt to withdraw up to the same amount again to exploit ordering differences
            // bound reentry amount to a reasonable value: withdraw half of current balance as attempt
            (uint256 u, uint256 b) = c.Acc(address(this));
            uint256 tryAmt = b >= 1 ? (b / 2) : 0;
            if (tryAmt > 0) {
                // perform reentrant Collect; this will only succeed on the buggy contract
                // ignore failures
                try c.Collect{value: 0}(tryAmt) {
                } catch {}
            }
        }
    }
}
